<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ProjectReader, type DramaGlobal, type DramaUsage } from '../../platform/project-reader'
import ProjectMedia from '../ProjectMedia.vue'
import DramaProse from './DramaProse.vue'
import { materialPreview, dramaText } from '../../platform/drama-presentation'
import DramaDocument from './DramaDocument.vue'
import DramaFile from './DramaFile.vue'
import DramaVersions from './DramaVersions.vue'
import DramaTips from './DramaTips.vue'
import DramaPublication from './DramaPublication.vue'
const props = defineProps<{ reader: ProjectReader; tab: string }>()
const route = useRoute(), router = useRouter(), q = (key: string) => typeof route.query[key] === 'string' ? route.query[key] as string : ''
const searchDraft = ref(q('find'))
watch(() => q('find'), value => { searchDraft.value = value })
function search() { void router.replace(link({ find: searchDraft.value || undefined })) }
const project = computed(() => props.reader.project!), drama = computed(() => props.reader.content!.ai_short_drama!)
const kinds = [{ key: 'script', label: '剧本正文' }, { key: 'character', label: '人物卡片' }, { key: 'wardrobe', label: '服装造型' }, { key: 'prop', label: '道具' }, { key: 'location', label: '场景' }, { key: 'sound', label: '声音' }, { key: 'music', label: '配乐' }]
const kindName = (key: string) => kinds.find(k => k.key === key)?.label || '设定'
const material = computed(() => drama.value.globals.find(g => g.key === q('material')))
const state = computed(() => q('state') ? material.value?.states.find(s => s.key === q('state')) : material.value?.states.find(s => s.key === material.value?.versions.find(v => v.key === q('version'))?.state_key) || material.value?.states[0])
const episode = computed(() => q('episode') ? drama.value.episodes.find(e => e.key === q('episode')) : drama.value.episodes[0])
const scene = computed(() => episode.value?.scenes.find(s => s.key === q('scene')))
const shot = computed(() => scene.value?.shots.find(s => s.key === q('shot')))
const delivery = computed(() => drama.value.deliverables.find(d => d.key === q('deliverable')))
const scriptKinds = [{ key: 'script', label: '剧本正文' }, { key: 'character', label: '人物小传' }, { key: 'location', label: '地点与场次' }, { key: 'wardrobe', label: '服装造型' }, { key: 'prop', label: '道具设定' }, { key: 'continuity', label: '逐镜连续性' }, { key: 'sound', label: '声音' }, { key: 'music', label: '配乐' }]
const activeKind = computed(() => material.value?.kind || q('kind') || (props.tab === 'script' ? 'script' : 'character'))
const rail = computed(() => props.tab === 'script' ? scriptKinds : kinds.filter(k => k.key !== 'script'))
const railTitle = computed(() => props.tab === 'script' ? '剧本与设定' : '素材设定')
const showRail = computed(() => ['script', 'materials'].includes(props.tab))
const activeName = computed(() => rail.value.find(k => k.key === activeKind.value)?.label || '设定')
const matches = (text: string) => !q('find') || text.toLocaleLowerCase().includes(q('find').toLocaleLowerCase())
const filtered = computed(() => drama.value.globals.filter(g => g.kind === activeKind.value && matches(g.name + ' ' + (g.description || '')) && (q('status') !== 'ready' || g.versions.length || g.file_ids.length) && (q('status') !== 'missing' || (!g.versions.length && !g.file_ids.length))))
const continuityFiles = computed(() => new Set(drama.value.continuity.flatMap(c => [...c.reference_file_ids, ...c.definition_refs.map(r => r.file_id)])))
const continuityEntries = computed(() => drama.value.episodes.flatMap(e => e.scenes.flatMap(s => s.shots.map(sh => ({ key: sh.key, title: sh.title, episode: e, scene: s, refs: sh.definition_refs.filter(r => continuityFiles.value.has(r.file_id) && r.anchor) })).filter(x => x.refs.length))))
const continuityEntry = computed(() => continuityEntries.value.find(e => e.key === q('continuity')))
const allShots = computed(() => drama.value.episodes.flatMap(e => e.scenes.flatMap(s => s.shots)))
const episodeShots = computed(() => episode.value?.scenes.flatMap(s => s.shots) || [])
const coverTitle = computed(() => project.value.manifest.name.split('·'))
const scriptGlobal = computed(() => drama.value.globals.find(g => g.kind === 'script'))
const reviewName = (value?: string) => ({ unreviewed: '待审核', in_review: '审核中', approved: '已有审核记录', rejected: '需修改' }[value || ''] || '审核未登记')
const categoryDescription: Record<string, string> = { script: '分集故事与对白', character: '身份、经历与人物关系', location: '空间、时段与场面调度', wardrobe: '人物在不同阶段的衣着', prop: '外观、用途与流转', continuity: '逐镜核对人物与物件状态', sound: '人物声线与环境声音', music: '情绪、节奏与音乐安排' }
function definitionVersion(kind: string) {
  const id = kind === 'continuity' ? drama.value.continuity[0]?.reference_file_ids[0] || drama.value.continuity[0]?.definition_refs[0]?.file_id : drama.value.globals.find(g => g.kind === kind)?.definition_refs[0]?.file_id
  const path = project.value.manifest.files.find(f => f.file_id === id)?.path
  const version = path?.match(/-v(\d+)\.[^.]+$/i)?.[1]
  return version ? `第 ${version} 稿` : '项目创作依据'
}
const shotCount = computed(() => allShots.value.length)
const budget = computed(() => allShots.value.reduce((n, s) => n + (s.duration_seconds || 0), 0))
const human = (text?: string | null) => dramaText(text, drama.value).replace(/\*\*/g, '')
const related = computed(() => drama.value.globals.filter(g => material.value && (material.value.input_global_keys.includes(g.key) || g.input_global_keys.includes(material.value.key))))
const episodeCharacters = computed(() => {
  const used = new Set(drama.value.usages.filter(u => u.target.episode_key === episode.value?.key).map(u => u.global_key))
  for (const g of drama.value.globals) if (used.has(g.key)) for (const key of g.input_global_keys) used.add(key)
  return drama.value.globals.filter(g => g.kind === 'character' && used.has(g.key))
})
const candidates = computed(() => drama.value.world_candidates.filter(c => material.value ? c.source.kind === 'global' && c.source.key === material.value.key : delivery.value ? c.source.kind === 'deliverable' && c.source.key === delivery.value.key : true))
const locations = computed(() => drama.value.globals.filter(g => g.kind === 'location' && matches(g.name + ' ' + (g.description || ''))))
function cardStatus(g: DramaGlobal) { return g.versions.length ? `${g.versions.length} 个制作版本 · ${g.selected_versions.length ? '已登记项目选用' : '尚未登记正式选用'}` : g.file_ids.length ? '已有成果 · 版本关系待整理' : '已有文字依据 · 待制作' }
function previewStatus(g: DramaGlobal) {
  const preview = materialPreview(g), v = preview.version
  return v ? `${g.states.find(s => s.key === v.state_key)?.name || '状态未整理'} · ${v.label} · ${{ unreviewed: '未审核', in_review: '审核中', approved: '此版已有审核记录', rejected: '需修改' }[v.review.state]} · ${preview.selected ? '项目选用' : '未选用'}` : ''
}
function categoryLink(kind: string) { return link({ kind, material: undefined, state: undefined, version: undefined, compare: undefined, scene: undefined, shot: undefined, find: undefined, status: undefined, continuity: undefined }) }
function shotLink(sceneKey: string, shotKey: string, tab = props.tab) { return link({ tab, episode: episode.value?.key, scene: sceneKey, shot: shotKey, material: undefined, state: undefined, version: undefined, compare: undefined }) }
function link(change: Record<string, string | undefined>) { return { path: route.path, query: { ...route.query, ...change } } }
function materialLink(g: DramaGlobal, version?: string, state?: string) { return link({ tab: 'materials', material: g.key, state, version, find: undefined, kind: g.kind, compare: undefined, episode: undefined, scene: undefined, shot: undefined, deliverable: undefined }) }
const back = computed(() => link({ material: undefined, state: undefined, version: undefined, compare: undefined, shot: undefined, scene: undefined, deliverable: undefined }))
const target = computed(() => [props.tab, q('material'), q('state'), q('episode'), q('scene'), q('shot'), q('deliverable'), q('version'), q('continuity')].join('/'))
const usages = computed(() => drama.value.usages.filter(u => material.value ? u.global_key === material.value.key : shot.value ? u.target.episode_key === episode.value?.key && (!u.target.scene_key || u.target.scene_key === scene.value?.key) && (!u.target.shot_key || u.target.shot_key === shot.value.key) : false))
function usageLabel(u: DramaUsage) { const e = drama.value.episodes.find(e => e.key === u.target.episode_key), s = e?.scenes.find(s => s.key === u.target.scene_key), sh = s?.shots.find(sh => sh.key === u.target.shot_key); return [e?.title, s?.title, sh?.title, u.segment?.label].filter(Boolean).join(' · ') }
function usageMaterial(u: DramaUsage) { const g = drama.value.globals.find(g => g.key === u.global_key)!; return [g.name, g.states.find(s => s.key === u.state_key)?.name || '状态未整理', g.versions.find(v => v.key === u.version_key)?.label || '制作版本未选定'].join(' · ') }
</script>
<template>
  <div class="short-drama" :class="{ 'with-rail': showRail }">
    <nav v-if="showRail" class="category-rail" :aria-label="railTitle"><h2>{{ railTitle }}</h2><RouterLink v-for="k in rail" :key="k.key" :class="{ active: activeKind === k.key }" :to="categoryLink(k.key)">{{ k.label }}</RouterLink></nav>
    <div class="workspace-body">
    <template v-if="q('material')">
      <RouterLink class="btn back-link" :to="back">返回{{ tab === 'script' ? '设定' : '素材' }}列表</RouterLink><p v-if="!material" class="empty">当前修订没有这项资料。</p>
      <p v-else-if="q('state') && !state" class="empty">当前修订没有这个状态，请返回资料列表重新选择。</p>
      <template v-else>
        <header class="section-head"><div><span class="muted">{{ activeName }}</span><h2>{{ material.name }}</h2></div></header>
        <div class="production-cols"><div class="stack">
          <template v-if="tab === 'materials'">
          <DramaVersions :reader="reader" :versions="material.versions.filter(v => !state || v.state_key === state.key)" :selections="material.selected_versions">          <p v-if="!material.states.length" class="muted">状态尚未整理，不默认视为干净、完好或日景。</p><nav v-else class="state-links" aria-label="查看状态"><RouterLink v-for="s in material.states" :key="s.key" :class="{ active: state?.key === s.key }" :to="link({ state: s.key, version: undefined, compare: undefined })">{{ s.name }}</RouterLink></nav></DramaVersions>
          <section class="panel"><h2>{{ material.kind === 'location' ? '场景状态：时段、天气与光源' : '连续性细节' }}</h2><template v-if="state"><div v-for="mark in state.marks" :key="mark.key" class="material-mark"><h3>{{ mark.part === '按原文' && mark.side === '按原文' ? '连续性要求' : mark.part + ' · ' + mark.side }}</h3><DramaProse :text="mark.description" :drama="drama" /><DramaDocument v-for="(r, i) in mark.reference_refs" :key="`${r.file_id}:${i}`" :reader="reader" :file-id="r.file_id" :anchor="r.anchor" :title="`细节参考 ${i + 1}`" /></div><p v-if="!state.marks.length" class="muted">本状态没有额外登记污损或破损标记；环境以状态依据为准。</p><DramaDocument v-for="(r, i) in state.definition_refs" :key="`${r.file_id}:${i}`" :reader="reader" :file-id="r.file_id" :anchor="r.anchor" :initially-expanded="!!r.anchor" :title="`状态依据 ${i + 1}`" /></template><p v-else class="muted">状态依据尚未整理。</p></section>
          </template>
          <section class="panel manuscript"><span class="eyebrow">文字设定与生成依据</span><h2>{{ material.name }}</h2><DramaProse :text="material.description || '说明尚未填写。'" :drama="drama" /><DramaDocument v-for="(r, i) in material.definition_refs" :key="`${r.file_id}:${i}`" :reader="reader" :file-id="r.file_id" :anchor="r.anchor" :title="`完整设定资料 ${i + 1}`" /></section>
          <section v-if="!material.versions.length && material.file_ids.length" class="panel"><h2>已有成果</h2><DramaFile v-for="(id, i) in material.file_ids" :key="id" :reader="reader" :file-id="id" :label="`成果 ${i + 1}`" /></section>
          <section v-if="material.reference_file_ids.length" class="panel"><h2>参考资料</h2><DramaFile v-for="(id, i) in material.reference_file_ids" :key="id" :reader="reader" :file-id="id" :label="`参考 ${i + 1}`" /></section>
        </div><aside class="stack"><section class="panel"><h2>关联内容</h2><RouterLink v-for="g in related" :key="g.key" class="related-link" :to="materialLink(g)">{{ g.name }} →</RouterLink><p v-if="!related.length" class="muted">与本项目的剧本及配套设定一同审阅。</p><RouterLink class="related-link" :to="link({ tab: tab === 'materials' ? 'script' : 'materials', version: undefined, compare: undefined })">{{ tab === 'materials' ? '阅读文字设定' : '查看制作素材' }} →</RouterLink></section><DramaPublication v-if="tab === 'materials'" :reader="reader" :candidates="candidates" /><section class="panel"><h2>使用位置</h2><p v-if="!usages.length" class="muted">尚未关联使用位置。</p><div v-for="u in usages" :key="u.key" class="row"><RouterLink :to="link({ tab: 'production', material: undefined, state: undefined, version: undefined, find: undefined, kind: undefined, compare: undefined, episode: u.target.episode_key, scene: u.target.scene_key, shot: u.target.shot_key })">{{ usageLabel(u) }} →</RouterLink><p class="muted">{{ usageMaterial(u) }}</p><details v-if="u.description"><summary>使用说明</summary><DramaProse :text="u.description" :drama="drama" /></details></div></section><DramaTips :project-id="project.project_id" :revision-id="project.revision_id" :target="target" /></aside></div>
      </template>
    </template>
    <template v-else-if="q('shot')">
      <RouterLink class="btn" :to="back">返回镜头列表</RouterLink><p v-if="!shot" class="empty">当前修订没有这个镜头。</p>
      <div v-else class="production-cols"><div class="stack"><section v-if="!shot.versions.length" class="panel"><h2>制作准备</h2><p class="empty">尚无制作候选，先核对素材选版、场景白模与灯光依据。</p><div class="row"><h3>场景与镜头白模</h3><p class="muted">本镜尚未登记可编辑工程与对应相机预览。</p><RouterLink class="related-link" :to="link({ view: 'spaces', shot: undefined, scene: undefined })">查看场景白模与灯光 →</RouterLink></div><div class="row"><h3>环境与灯光</h3><p class="muted">本镜段落固定相应状态；具体工程灯值与曝光以实际试光记录为准。</p></div></section><DramaVersions v-else :reader="reader" :versions="shot.versions" :selections="shot.selected_versions" /><section class="panel"><h2>{{ shot.title }}</h2><DramaProse :text="shot.overview || '镜头说明尚未填写。'" :drama="drama" /><p class="muted">{{ shot.duration_seconds == null ? '剧本时长未填写' : `剧本预算 ${shot.duration_seconds} 秒` }}</p><DramaDocument v-for="(r, i) in shot.definition_refs" :key="`${r.file_id}:${i}`" :reader="reader" :file-id="r.file_id" :anchor="r.anchor" :title="`剧本与连续性依据 ${i + 1}`" /><div v-for="s in [...shot.segments].sort((a, b) => a.order - b.order)" :key="s.key" class="row">{{ s.order }} · {{ s.label }}</div></section><section v-if="!shot.versions.length && shot.result_file_ids.length" class="panel"><h2>已有结果 · 版本关系未整理</h2><DramaFile v-for="(id, i) in shot.result_file_ids" :key="id" :reader="reader" :file-id="id" :label="`镜头结果 ${i + 1}`" /></section></div><aside class="stack"><section class="panel"><h2>固定素材与场景状态</h2><p v-if="!usages.length" class="muted">素材、白模与灯光输入尚未关联。</p><div v-for="u in usages" :key="u.key" class="row"><RouterLink :to="materialLink(drama.globals.find(g => g.key === u.global_key)!, u.version_key || undefined, u.state_key || undefined)">{{ usageMaterial(u) }} →</RouterLink><p class="muted">{{ u.segment?.label || '场次／整镜使用' }}</p></div></section><section v-if="shot.continuity_keys.length" class="panel"><h2>连续性核对</h2><div v-for="c in drama.continuity.filter(c => shot?.continuity_keys.includes(c.key))" :key="c.key" class="row"><h3>{{ c.name }}</h3><DramaProse :text="c.description" :drama="drama" /><DramaDocument v-for="(r, i) in c.definition_refs" :key="`${r.file_id}:${i}`" :reader="reader" :file-id="r.file_id" :anchor="r.anchor" :title="`连续性资料 ${i + 1}`" /></div></section><DramaTips :project-id="project.project_id" :revision-id="project.revision_id" :target="target" /></aside></div>
    </template>
    <template v-else-if="tab === 'delivery'">
      <template v-if="q('deliverable')"><RouterLink class="btn" :to="back">返回成果列表</RouterLink><template v-if="delivery"><h2>{{ delivery.title }}</h2><p class="prose">{{ delivery.description }}</p><DramaVersions :reader="reader" :versions="delivery.versions" :selected-key="delivery.selected_version_key" /><section class="panel"><h2>实际交付记录</h2><p v-if="!delivery.delivery_record_file_ids.length" class="muted">尚未登记实际交付。导出或下载不代表客户已收到。</p><DramaDocument v-for="(id, i) in delivery.delivery_record_file_ids" :key="id" :reader="reader" :file-id="id" :title="`交付记录 ${i + 1}`" /></section><section v-if="!delivery.versions.length" class="panel"><h2>已有文件</h2><DramaFile v-for="(id, i) in delivery.file_ids" :key="id" :reader="reader" :file-id="id" :label="`成果文件 ${i + 1}`" /></section><DramaTips :project-id="project.project_id" :revision-id="project.revision_id" :target="target" /></template><p v-else class="empty">当前修订没有这项成果。</p></template>
      <template v-else><h2>成果与交付</h2><p class="muted">成片、工程与交付包各自固定版本；新候选不会改变历史成片。</p><div class="material-grid"><RouterLink v-for="d in drama.deliverables" :key="d.key" class="production-card" :to="link({ deliverable: d.key, version: undefined, compare: undefined })"><h3>{{ d.title }}</h3><p class="prose">{{ d.description }}</p><p class="muted">{{ d.versions.find(v => v.key === d.selected_version_key)?.label || '当前选用未整理' }} · {{ d.delivery_record_file_ids.length ? '有交付记录' : '尚无交付记录' }}</p></RouterLink></div><p v-if="!drama.deliverables.length" class="empty">尚未登记成果项。</p><section v-for="e in drama.episodes.filter(e => e.output_file_id || e.edit_file_id)" :key="e.key" class="panel"><h3>{{ e.title }} · 已有分集文件</h3><DramaFile v-if="e.output_file_id" :reader="reader" :file-id="e.output_file_id" label="成片" /><DramaFile v-if="e.edit_file_id" :reader="reader" :file-id="e.edit_file_id" label="编辑工程" /></section></template>
    </template>
    <template v-else-if="tab === 'overview'">
      <div class="overview-grid"><section class="story-cover"><div class="cover-label">{{ coverTitle[0] }}<template v-if="coverTitle.length > 1"><br><span>{{ coverTitle.slice(1).join('·') }}</span></template></div><div><span class="eyebrow">故事提要</span><p>{{ human(reader.content?.overview) }}</p><RouterLink class="btn primary" :to="link({ tab: 'script', kind: undefined })">阅读剧本 →</RouterLink></div></section><aside class="panel"><h2>本轮审阅</h2><p class="muted">先确认故事、人物与配套设定，再据此准备素材。</p><dl><dt>篇幅</dt><dd>{{ drama.episodes.length }} 集 · {{ shotCount }} 镜</dd><dt>画面预算</dt><dd>{{ budget ? `${Math.floor(budget / 60)} 分 ${budget % 60} 秒` : '尚未填写' }}</dd><dt>剧本</dt><dd>{{ scriptGlobal?.name || definitionVersion('script') }} · {{ reviewName(scriptGlobal?.definition_review.state) }}</dd><dt>制作素材</dt><dd>{{ drama.globals.filter(g => g.versions.length).length }} 项已有候选</dd></dl><p class="muted">各版本的审核和选用分别记录，可从素材设定查看。</p></aside></div>
      <header class="section-head"><h2>剧本与配套设定</h2><span class="muted">一部作品，共用一套创作依据</span></header><div class="document-grid"><RouterLink v-for="k in scriptKinds" :key="k.key" class="document-card" :to="link({ tab: 'script', kind: k.key })"><span class="doc-symbol">{{ k.label.slice(0, 1) }}</span><div><span class="muted">{{ definitionVersion(k.key) }}</span><h3>{{ k.label }}</h3><p>{{ categoryDescription[k.key] }}</p></div><span>↗</span></RouterLink></div><section class="future"><h2>后续创作</h2><p class="muted">人物小传用于人物形象，服装设定用于造型，地点与道具设定用于场景制作。选定成果可整理为数字世界资产，供后续作品复用。</p></section>
    </template>
    <template v-else-if="tab === 'materials' || tab === 'script'">
      <header class="section-head"><div><span class="muted">{{ tab === 'materials' ? '项目共用素材' : '剧本与配套设定' }}</span><h2>{{ activeName }}</h2><RouterLink v-if="activeKind === 'location'" class="related-link" :to="link({ tab: 'production', view: 'spaces', kind: undefined })">查看白模与灯光设计 →</RouterLink></div><span v-if="activeKind !== 'script' && activeKind !== 'continuity'" class="muted">{{ filtered.length }} 项</span></header>
      <template v-if="tab === 'script' && activeKind === 'script'">
        <nav class="episode-tabs" aria-label="分集"><RouterLink v-for="(e, i) in drama.episodes" :key="e.key" :class="{ active: e.key === episode?.key }" :to="link({ episode: e.key, scene: undefined, shot: undefined })">第 {{ i + 1 }} 集</RouterLink></nav>
